import json, numpy as np, os

conditions = ['clean', 'contam_15', 'contam_50']
data = {}
for c in conditions:
    path = f'results/{c}_results.json'
    if os.path.exists(path):
        with open(path) as f:
            d = json.load(f)
        data[c] = d
        print(f"{c}: lz*={d['lz_star']:.4f}, acc={d['accuracy_overall']:.4f}, theta={d['theta_mle']:.4f}")
        print(f"  acc_seen={d.get('accuracy_seen')}, acc_unseen={d.get('accuracy_unseen'):.4f}" if d.get('accuracy_unseen') else "")
        print(f"  lz*_seen={d.get('lz_star_seen')}, lz*_unseen={d.get('lz_star_unseen'):.4f}" if d.get('lz_star_unseen') else "")
    else:
        print(f"{c}: NO RESULTS FILE")

if 'clean' in data:
    clean_lz = data['clean']['lz_star']
    print(f"\n=== Delta lz* (vs clean) ===")
    for c in ['contam_15', 'contam_50']:
        if c in data:
            delta = data[c]['lz_star'] - clean_lz
            print(f"{c}: Δlz*={delta:.4f}")

    print(f"\n=== Cross-model comparison ===")
    print(f"Qwen pilot (n=3): clean mean=7.345, contam_15 lz*=3.005, d=-3.58")
    print(f"Llama: clean lz*={clean_lz:.4f}")
    for c in ['contam_15', 'contam_50']:
        if c in data:
            print(f"Llama {c}: lz*={data[c]['lz_star']:.4f}, Δlz*={data[c]['lz_star']-clean_lz:.4f}")

output = {
    'model': 'Llama-3.1-8B-Instruct',
    'conditions': {}
}
for c in conditions:
    if c in data:
        output['conditions'][c] = {
            'theta_mle': data[c]['theta_mle'],
            'lz_star': data[c]['lz_star'],
            'accuracy_overall': data[c]['accuracy_overall'],
            'accuracy_seen': data[c].get('accuracy_seen'),
            'accuracy_unseen': data[c].get('accuracy_unseen'),
            'lz_star_seen': data[c].get('lz_star_seen'),
            'lz_star_unseen': data[c].get('lz_star_unseen'),
            'n_items': data[c]['n_items'],
            'n_seen': data[c]['n_seen'],
            'n_unseen': data[c]['n_unseen'],
        }

with open('results/llama_summary.json', 'w') as f:
    json.dump(output, f, indent=2)
print(f"\nSaved results/llama_summary.json")
print(json.dumps(output, indent=2, default=str))
